<?php
require __DIR__.'/includes/bootstrap.php';$_SESSION['cart']??=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);$q=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);if($id&&$q&&$q>0&&$q<=20){$s=$pdo->prepare('SELECT id FROM products WHERE id=? AND active=1');$s->execute([$id]);if($s->fetch())$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+$q;}redirect('/cart.php');}
$items=[];$total=0;if($_SESSION['cart']){$ids=array_map('intval',array_keys($_SESSION['cart']));$ph=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,price FROM products WHERE id IN ($ph)");$s->execute($ids);foreach($s->fetchAll() as $p){$q=(int)$_SESSION['cart'][$p['id']];$sub=$q*(float)$p['price'];$total+=$sub;$items[]=$p+['quantity'=>$q,'subtotal'=>$sub];}}
$pageTitle='Cart';require __DIR__.'/includes/header.php';?><h1>Shopping Cart</h1><?php if(!$items):?><p>Your cart is empty.</p><?php else:?><table><tr><th>Product</th><th>Qty</th><th>Subtotal</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=(int)$i['quantity']?></td><td>$<?=number_format($i['subtotal'],2)?></td></tr><?php endforeach;?></table><p class="price">Total: $<?=number_format($total,2)?></p><?php if(!empty($_SESSION['user_id'])):?><form action="/checkout.php" method="post"><button>Place demo order</button></form><?php else:?><p><a href="/login.php">Log in</a> to complete checkout.</p><?php endif;?><?php endif;?><?php require __DIR__.'/includes/footer.php';?>
